package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Stream;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;
import org.junit.jupiter.api.io.TempDir;

class MashSummaryCliTest {
    @TempDir static Path temp;
    private static Path nativeSource,zeroSource;
    private static final Runnable CHECK=()->{};
    private record Run(int code,String out,String err) { }
    private static Run run(String... args){return runWith(()->{},args);}
    private static Run runWith(Runnable hook,String...args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int code=MashSummaryCli.run(args,new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8),hook);return new Run(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    private static void nativeRun(String...args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();assertEquals(0,MashToolsCli.run(args,new PrintStream(out),new PrintStream(err)),err.toString(StandardCharsets.UTF_8));}
    private static Path nativeSource(boolean zero)throws Exception {
        if(zero?zeroSource!=null:nativeSource!=null)return zero?zeroSource:nativeSource;
        Path folder=Files.createTempDirectory(temp,zero?"zero-":"native-");Path exported=folder.resolve("export");nativeRun("--export-example",exported.toString());Path input=exported.resolve("fit-input");
        if(zero){Path settings=input.resolve("settings.tsv");Files.writeString(settings,Files.readString(settings).replace("point_mass\ttrue","point_mass\tfalse").replace("prior\tnullbiased","prior\tuniform"));Files.writeString(input.resolve("effects.tsv"),"feature\tA\tB\n0001\t0\t0\n");}
        Path source=folder.resolve("result");nativeRun("--input",input.toString(),"--out",source.toString());if(zero)zeroSource=source;else nativeSource=source;return source;
    }
    private static Path request(String name,boolean composite,boolean zero)throws Exception {
        Path exported=temp.resolve(name+"-export");Run result=run("--export-template",nativeSource(zero).toString(),"--out",exported.toString());assertEquals(0,result.code(),result.err());Path input=exported.resolve("input");
        if(composite){Path settings=input.resolve("settings.tsv");Files.writeString(settings,Files.readString(settings).replace("composite_mode\toff","composite_mode\tmarginal_sign_product")+"nominal_p_threshold\t0.05\nminimum_nominal\t2\nscore_threshold\t0.9\n");Files.writeString(input.resolve("groups.tsv"),"group\tcondition\nboth\tA\nboth\tB\nfirst\tA\n");Files.writeString(input.resolve("nominal-p.tsv"),"feature\tA\tB\n0001\t0.001\t0.001\n");}return input;
    }
    private static Path admitted(String name,boolean composite)throws Exception {Path input=request(name,composite,false),out=temp.resolve(name);Run result=run("--native-bundle",nativeSource(false).toString(),"--input",input.toString(),"--out",out.toString());assertEquals(0,result.code(),result.err());assertTrue(Files.exists(out.resolve("COMPLETED.json")));assertFalse(Files.exists(out.resolve("FAILURE.json")));return out;}
    private static Map<String,Object> object(Object value){assertInstanceOf(Map.class,value);var result=new LinkedHashMap<String,Object>();for(var e:((Map<?,?>)value).entrySet()){assertInstanceOf(String.class,e.getKey());result.put((String)e.getKey(),e.getValue());}return result;}
    private static Map<String,Object> json(Path path)throws IOException{return object(MashFiles.json(path,8_388_608));}
    private static void write(Path path,Object value)throws IOException {Files.writeString(path,MashJson.json(value)+"\n",StandardCharsets.UTF_8);}
    private static void reseal(Path root)throws IOException {var manifest=json(root.resolve("manifest.json"));var inventory=MashFiles.inventory(root,MashSummaryLimits.defaults().files(),CHECK);var files=new TreeMap<>(inventory.files());files.remove("manifest.json");files.remove("COMPLETED.json");manifest.put("files",files);manifest.put("directories",new java.util.TreeSet<>(inventory.directories()));write(root.resolve("manifest.json"),manifest);var marker=json(root.resolve("COMPLETED.json"));marker.put("manifest",MashFiles.pin(root.resolve("manifest.json"),8_388_608,CHECK));write(root.resolve("COMPLETED.json"),marker);}
    private static void hashes(Path root)throws IOException {var files=new TreeMap<>(MashFiles.inventory(root,MashLimits.defaults(),CHECK).files());files.remove("SHA256SUMS");StringBuilder s=new StringBuilder();for(var e:files.entrySet())s.append(e.getValue().sha256()).append("  ").append(e.getKey()).append('\n');Files.writeString(root.resolve("SHA256SUMS"),s,StandardCharsets.UTF_8);}
    private static void resealNative(Path root)throws IOException {hashes(root.resolve("execution/model"));hashes(root.resolve("execution"));reseal(root);}
    private static void reject(Path root)throws IOException {var before=MashFiles.inventory(root,MashSummaryLimits.defaults().files(),CHECK);Run checked=run("--verify",root.toString());assertEquals(2,checked.code(),checked.err());assertTrue(checked.err().contains("FAIL2"));assertTrue(checked.err().contains("Required action"));assertEquals(before,MashFiles.inventory(root,MashSummaryLimits.defaults().files(),CHECK));assertFalse(Files.exists(root.resolve("FAILURE.json")));}
    private static Run produce(Path source,Path request,Path output){return run("--native-bundle",source.toString(),"--input",request.toString(),"--out",output.toString());}
    private static void copy(Path source,Path target)throws IOException {try(var walk=Files.walk(source)){for(Path p:walk.toList()){Path q=target.resolve(source.relativize(p));if(Files.isDirectory(p))Files.createDirectories(q);else Files.copy(p,q);}}}

    @Test void helpLimitsAndTemplateDoNotInventNominalPValues()throws Exception {assertEquals(0,run("--help").code());var limits=run("--default-limits");assertEquals(0,limits.code());MashSummaryLimits.parse(SimpleJson.parse(limits.out()));Path input=request("template",false,false);assertFalse(Files.exists(input.resolve("nominal-p.tsv")));assertFalse(Files.exists(input.resolve("COMPLETED.json")));assertEquals("condition\nA\nB\n",Files.readString(input.resolve("significance-conditions.tsv")));}
    @Test void completeSummaryCapturesSourceAndVerifiesWithoutProducerPaths()throws Exception {Path source=temp.resolve("portable-source");copy(nativeSource(false),source);Path input=request("portable",false,false),out=temp.resolve("portable");assertEquals(0,produce(source,input,out).code());Files.move(source,temp.resolve("portable-source-retained"));Files.move(input,temp.resolve("portable-request-retained"));assertEquals(0,run("--verify",out.toString()).code());assertTrue(Files.readString(out.resolve("results/significance.tsv")).contains("0001\t"));assertFalse(Files.exists(out.resolve("results/marginal-sign-products.tsv")));}
    @Test void marginalProductsKeepNominalGatesAndGroupMembershipExplicit()throws Exception {Path root=admitted("products",true);String text=Files.readString(root.resolve("results/marginal-sign-products.tsv"));assertTrue(text.contains("0001\tboth\t"));assertTrue(text.contains("\t2\ttrue\ttrue"));assertTrue(text.contains("\t1\tfalse\tfalse"));assertEquals(0,run("--verify",root.toString()).code());assertEquals(Boolean.FALSE,json(root.resolve("COMPLETED.json")).get("joint_probability_inferred"));}
    @Test void inclusiveCountsDoNotChangeStrictPairwiseSourceSelection()throws Exception {Path input=request("inclusive",false,true);Path settings=input.resolve("settings.tsv");Files.writeString(settings,Files.readString(settings).replace("lfsr_threshold\t0.05","lfsr_threshold\t0.5").replace("significance_boundary\tstrict","significance_boundary\tinclusive"));Path out=temp.resolve("inclusive");Run result=produce(nativeSource(true),input,out);assertEquals(0,result.code(),result.err());assertTrue(Files.readString(out.resolve("results/significance.tsv")).contains("\t2\ttrue"));assertTrue(Files.readString(out.resolve("results/pairwise.tsv")).contains("EMPTY_SELECTED_POPULATION\tNA"));}
    @Test void selectedZeroRatiosRemainUndefinedAndEmitProminentWarnings()throws Exception {Path input=request("undefined",false,true);Path settings=input.resolve("settings.tsv");Files.writeString(settings,Files.readString(settings).replace("lfsr_threshold\t0.05","lfsr_threshold\t1"));Path out=temp.resolve("undefined");Run result=produce(nativeSource(true),input,out);assertEquals(0,result.code(),result.err());assertTrue(result.err().contains("undefined pairs=4"),result.err());assertTrue(Files.readString(out.resolve("results/pairwise.tsv")).contains("UNDEFINED_SELECTED_RATIO\tNA"));}
    @Test void nominalIdentityMismatchFailsWithoutAnAdmittedPrefix()throws Exception {Path input=request("bad-nominal",true,false);Files.writeString(input.resolve("nominal-p.tsv"),"feature\tB\tA\n1\t0.001\t0.001\n");Path out=temp.resolve("bad-nominal");assertEquals(2,produce(nativeSource(false),input,out).code());assertFalse(Files.exists(out.resolve("COMPLETED.json")));assertTrue(Files.readString(out.resolve("WARNINGS.md")).contains("FAIL2"));}
    @Test void missingAndUnusedRequestFilesFailClosed()throws Exception {Path input=request("missing",true,false);Files.move(input.resolve("nominal-p.tsv"),input.getParent().resolve("nominal-retained.tsv"));Path out=temp.resolve("missing");assertEquals(2,produce(nativeSource(false),input,out).code());assertFalse(Files.exists(out.resolve("native")));Path other=request("unused",false,false);Files.writeString(other.resolve("unused.tsv"),"unused\n");assertEquals(2,produce(nativeSource(false),other,temp.resolve("unused")).code());}
    @Test void duplicateGroupsAndSelectedConditionsAreNotSilentlyDeduplicated()throws Exception {Path input=request("duplicate-group",true,false);Files.writeString(input.resolve("groups.tsv"),"group\tcondition\nx\tA\nx\tA\n");assertEquals(2,produce(nativeSource(false),input,temp.resolve("duplicate-group")).code());Path other=request("duplicate-condition",false,false);Files.writeString(other.resolve("significance-conditions.tsv"),"condition\nA\nA\n");assertEquals(2,produce(nativeSource(false),other,temp.resolve("duplicate-condition")).code());}
    @Test void unsupportedFormalTestSkipsWithoutProductSubstitutionOrSourceReplay()throws Exception {Path input=request("formal",false,false);Path settings=input.resolve("settings.tsv");Files.writeString(settings,Files.readString(settings).replace("composite_mode\toff","composite_mode\tformal_composite"));Path out=temp.resolve("formal");Run result=produce(nativeSource(false),input,out);assertEquals(3,result.code());assertTrue(result.err().contains("SKIP3"));assertTrue(result.err().contains("No marginal-product substitution"));assertFalse(Files.exists(out.resolve("native")));assertFalse(Files.exists(out.resolve("COMPLETED.json")));}
    @Test void currentVerifierCeilingsCannotBeRaisedByCapturedLimits()throws Exception {Path root=admitted("ceilings",false),file=temp.resolve("lower-ceilings.json");var limits=object(SimpleJson.parse(MashJson.json(MashSummaryLimits.defaults())));var summary=object(limits.get("summary"));summary.put("work",1);limits.put("summary",summary);write(file,limits);var before=MashFiles.inventory(root,MashSummaryLimits.defaults().files(),CHECK);Run result=run("--verify",root.toString(),"--limits",file.toString());assertEquals(2,result.code());assertTrue(result.err().contains("current caller ceiling"));assertEquals(before,MashFiles.inventory(root,MashSummaryLimits.defaults().files(),CHECK));}
    @Test void existingAndOverlappingOutputsRemainUntouched()throws Exception {Path source=nativeSource(false),input=request("overlap",false,false);var before=MashFiles.inventory(source,MashLimits.defaults(),CHECK);assertEquals(2,produce(source,input,source).code());assertEquals(before,MashFiles.inventory(source,MashLimits.defaults(),CHECK));Path existing=temp.resolve("existing");Files.createDirectory(existing);Files.writeString(existing.resolve("keep"),"preserve");assertEquals(2,produce(source,input,existing).code());assertEquals("preserve",Files.readString(existing.resolve("keep")));}
    @Test void addedEmptyDirectoryFailsEvenAfterResealing()throws Exception {Path root=admitted("extra-directory",false);Files.createDirectory(root.resolve("extra"));reseal(root);reject(root);}
    @Test void finalizationGuardRevokesCompletionAndRetainsRejectedMarker()throws Exception {Path input=request("finalization",false,false),root=temp.resolve("finalization");Run result=runWith(()->{try{Files.writeString(root.resolve("results/pairwise.tsv"),"changed after marker\n");}catch(IOException error){throw new java.io.UncheckedIOException(error);}},"--native-bundle",nativeSource(false).toString(),"--input",input.toString(),"--out",root.toString());assertEquals(2,result.code());assertFalse(Files.exists(root.resolve("COMPLETED.json")));assertTrue(Files.exists(root.resolve("REJECTED-COMPLETION.json")));assertTrue(Files.exists(root.resolve("FAILURE.json")));}
    @Test void interruptedAnalysisNeverGetsACompletionMarker()throws Exception {Path input=request("cancelled",false,false),root=temp.resolve("cancelled");Thread.currentThread().interrupt();try{assertEquals(2,produce(nativeSource(false),input,root).code());assertFalse(Files.exists(root.resolve("COMPLETED.json")));}finally{Thread.interrupted();}}
    @Test void completeOutputBudgetRejectsCaptureBeforeOversizedNativeCopy()throws Exception {
        Path exported=temp.resolve("large-export");nativeRun("--export-example",exported.toString());Path input=exported.resolve("predict-input");copy(nativeSource(false).resolve("execution/model"),input.resolve("model"));
        StringBuilder effects=new StringBuilder("feature\tA\tB\n"),errors=new StringBuilder("feature\tA\tB\n"),populations=new StringBuilder("feature\ttrain\tstrong\ttarget\n");
        for(int i=0;i<1000;i++){String id="row-"+i;effects.append(id).append("\t1\t2\n");errors.append(id).append("\t1\t1\n");populations.append(id).append("\t0\t0\t1\n");}
        Files.writeString(input.resolve("effects.tsv"),effects);Files.writeString(input.resolve("standard-errors.tsv"),errors);Files.writeString(input.resolve("populations.tsv"),populations);Path large=temp.resolve("large-native");nativeRun("--input",input.toString(),"--out",large.toString());
        Path req=request("tiny-budget",false,false),root=temp.resolve("tiny-budget"),caps=temp.resolve("tiny-budget.json");var limits=object(SimpleJson.parse(MashJson.json(MashSummaryLimits.defaults())));limits.put("bundleBytes",65536);write(caps,limits);
        Run result=run("--native-bundle",large.toString(),"--input",req.toString(),"--out",root.toString(),"--limits",caps.toString());assertEquals(2,result.code());assertTrue(result.err().contains("before copying"),result.err());assertFalse(Files.exists(root.resolve("native")));assertFalse(Files.exists(root.resolve("COMPLETED.json")));assertTrue(Files.readString(root.resolve("WARNINGS.md")).contains("FAIL2"));
    }
    @Test void malformedUtf8NominalInputIsNotReplacedWithMissingValues()throws Exception {Path input=request("utf8",true,false);Files.write(input.resolve("nominal-p.tsv"),new byte[]{(byte)0xc3,(byte)0x28});assertEquals(2,produce(nativeSource(false),input,temp.resolve("utf8")).code());}
    @Test void declaredNativeWorkCannotBypassCurrentReplayLimits()throws Exception {Path source=temp.resolve("native-limits");copy(nativeSource(false),source);var manifest=json(source.resolve("manifest.json"));var limits=object(manifest.get("limits"));var execution=object(limits.get("execution"));var fit=object(execution.get("fit"));fit.put("totalGaussianWork",100_000_000_001L);execution.put("fit",fit);limits.put("execution",execution);manifest.put("limits",limits);write(source.resolve("manifest.json"),manifest);Path input=request("native-limit-request",false,false),root=temp.resolve("native-limit-output");Run result=produce(source,input,root);assertEquals(2,result.code());assertTrue(result.err().contains("current caller ceiling"));assertFalse(Files.exists(root.resolve("results")));}
    @Test void resealedNativePosteriorStillRequiresCompleteModelReplay()throws Exception {Path root=admitted("native-tamper",false);Path mean=root.resolve("native/execution/posterior/mean.tsv");var rows=new ArrayList<>(Files.readAllLines(mean));var values=rows.get(0).split("\t");values[0]=Double.toString(Double.parseDouble(values[0])+.25);rows.set(0,String.join("\t",values));Files.write(mean,rows);resealNative(root.resolve("native"));reseal(root);reject(root);}
    @TestFactory Stream<DynamicTest> resealedScientificAndScopeTampering() {
        var tests=new ArrayList<DynamicTest>();for(String name:List.of("counts","fraction","product","log","positive-log","warnings","session"))tests.add(DynamicTest.dynamicTest("resealed-summary-"+name,()->{
            Path root=admitted("tamper-"+name,true);if(name.equals("warnings"))Files.writeString(root.resolve("WARNINGS.md"),"looks complete\n");else if(name.equals("session")){var session=json(root.resolve("session.json"));session.put("posterior_source","unverified");write(root.resolve("session.json"),session);}else {
                Path file=root.resolve("results/"+(name.equals("counts")?"significance.tsv":name.equals("fraction")?"pairwise.tsv":"marginal-sign-products.tsv"));var rows=new ArrayList<>(Files.readAllLines(file));String[] values=rows.get(1).split("\t",-1);int column=name.equals("counts")?2:name.equals("fraction")?6:name.equals("product")?2:3;values[column]=name.equals("counts")?"999":name.equals("positive-log")?"0.0000000000001":name.equals("log")?"-0.01":"0.123";rows.set(1,String.join("\t",values));Files.write(file,rows);
            }reseal(root);reject(root);
        }));return tests.stream();
    }
}
